import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total = scanner.nextInt();
        List<Integer> numbers = new ArrayList<>(total);
        for (int i = 0; i < total; i++) {
            numbers.add(scanner.nextInt());
        }
        int max_diff = scanner.nextInt();
        Collections.sort(numbers);
        int max_group_size = 0;
        for (int start_idx = 0; start_idx < total; start_idx++) {
            int count = 0;
            for (int j = start_idx; j < total; j++) {
                if (numbers.get(j) <= numbers.get(start_idx) + max_diff) {
                    count++;
                }
            }
            max_group_size = Math.max(max_group_size, count);
        }
        System.out.println(max_group_size);
        scanner.close();
    }
}
